// 后端服务基础地址：开发时可改为你的服务器地址
const BASE_URL = 'http://localhost:3000'

export async function fetchLatestMetrics() {
	const res = await uni.request({
		url: `${BASE_URL}/metrics/latest`,
		method: 'GET'
	})
	// uni.request 返回 [err, res] in callback 风格，这里使用 Promise 形式
	// 当使用 Promise 形式时，返回的是 [response]，HBuilderX 版本差异可能存在
	return res[1] ? res[1].data : res.data
}

export function setApiBaseUrl(url) {
	// 简单可变配置
	if (url) {
		// 非严格校验，仅用于开发
		// eslint-disable-next-line no-global-assign
		BASE_URL = url
	}
}

